/* Whole-function specialisation on CeTTa's matcher (t-2026-11-18-cettapack-fnspec).
 *
 * A plan (generated by tools/fnspecc.py) is one MeTTa function compiled to C:
 * CeTTa's conjunction matcher (space_query_conjunction), the generated row
 * function (condition in C, template by bindings_apply), the shape's wrapper
 * (stream / collapse) and CeTTa's result conventions.  This runtime adds the
 * guards and the residual, and registers the function as an embedding callback
 * cpk-fnspec:<f> (and, for the fn-hosted baseline, cpk-hosted:<f>: the
 * function's match alone behind a callable, no guard).
 *
 * Guards (docs/FNSPEC_PLAN.md B3-B6), in the order a call meets them:
 *   forced INVALID (test mode)                          -> residual
 *   &self program token moved since the last check:     re-read the definition of f
 *     (exactly one equation, alpha-equal to the compiled one; no declaration of f),
 *     the equations and declarations of every builtin the body uses (equal to a
 *     fresh engine's), no catch-all equation; INVALID until the next revision
 *   arguments: the space is a space; the others ground and in normal form
 *   per row: compared values of the kind the comparison was compiled for
 *   per answer: normal form (no variable, no grounded operation or builtin head,
 *     no symbol that heads an equation in &self)
 * Any failure -> the residual: CeTTa evaluates (f args...) in the same engine. */
#ifndef CPK_FNSPEC_H
#define CPK_FNSPEC_H
#include "cetta_embed.h"
#include "cetta_embed_native.h"
#include "match.h"
#include "space.h"
#include <stdbool.h>
#include <stdint.h>

typedef enum { FS_STREAM_DATA, FS_COLLAPSE_DATA, FS_COLLAPSE_FILTER, FS_STREAM_FILTER,
               FS_ONCE_DATA, FS_ONCE_FILTER, FS_EXIST_DATA, FS_EXIST_FILTER,
               /* fnspec 3: template trees (if/case/empty/data/boolean) */
               FS_STREAM_COND, FS_COLLAPSE_COND, FS_ONCE_COND, FS_EXIST_COND } FsShape;
typedef enum { FS_EQ, FS_ALPHA, FS_LT, FS_GT, FS_LE, FS_GE } FsCmp;

typedef struct FsRt FsRt;
typedef struct FsCall FsCall;
typedef struct { const char *name; unsigned arity; } FsBuiltin;

typedef struct {
    const char *site, *function;
    unsigned arity;
    FsShape shape;
    int space_arg;               /* index of the argument that is the space, or -1 */
    const char *space_token;     /* the named space token when space_arg < 0 */
    const char *parts;           /* (_ LHS (P1..Pn) TMPL (CVARS) (CONSTS) (HVARS) (SEEDS)) */
    const char *equation;        /* the compiled equation */
    const char *hosted_def;      /* (= (f-h ...) ...): the function with its match hosted */
    const char *digest;
    const char *definitions;     /* the site file's definitions, loaded into &self */
    FsBuiltin builtins[16];
    unsigned n_builtins;
    unsigned n_cvars, n_consts, n_patterns;
    int once;                    /* the body is (collapse (once (match ...))) [inside an existence test] */
    int exist;                   /* 0 no existence test; 1 (not (== W ())): True when a row survives;
                                    2 (== W ()): True when none does */
    int (*row)(FsCall *c, Bindings *row, Arena *a, Atom **answer);
    int tree;                    /* fnspec 3: the template is a tree; TMPL in parts is the tuple of its
                                    data leaves and case patterns (FS_TMPL(i)) */
    int needs_bool;              /* a tree leaf answers a boolean (he's True/False) */
    const char *kb, *queries, *origin, *setup;
    const char *profile;         /* CeTTa he profile the site runs in ("" = the default he profile) */
    const char *load;            /* "" definitions loaded into &self; "import": from a module (import!) */
} FsPlan;

typedef struct {
    uint64_t calls, spec_calls, residual_calls;
    uint64_t forced, invalid, arg_rejects, row_aborts, revalidations;
    uint64_t hosted_calls;
} FsStats;

struct FsRt {
    const FsPlan *plan;
    cetta_engine_t *engine;
    cetta_atom_t *parts_h, *equation_h, *def_query_h, *decl_query_h;
    cetta_atom_t **builtin_query_h;      /* 2 per builtin: equations, declarations */
    char **baseline;                     /* their canonical results in a fresh engine */
    Atom *tmpl, *hvars;
    Atom **tmpls;                        /* fnspec 3: a tree's template atoms */
    Atom *true_a, *false_a;              /* native atoms of true_h, false_h */
    Atom **pats, **cvars, **consts, **lhs_args;
    Atom *equation;
    Space *self;
    Atom *named_space;                   /* the space atom of space_token */
    SpaceProgramToken tok;
    bool tok_valid, valid, force_invalid;
    bool once_unavailable;               /* once is not CeTTa's first-answer builtin in this engine */
    cetta_atom_t *true_h, *false_h;      /* he's results of (== () ()) and (== () (x)), from a fresh engine */
    bool eq_mismatch;                    /* fnspec 3: the live engine's existence-test answers differ from them */
    const char *invalid_reason;
    FsStats st;
    cetta_atom_t *callable, *hosted;
};

struct FsCall {
    FsRt *rt;
    Atom *const *args;                   /* native atoms of the call's arguments */
};

#define FS_ARG(i) ((Atom *)c->args[(i)])
#define FS_ROWVAR(j) bindings_apply(row, a, c->rt->cvars[(j)])
#define FS_CONST(k) (c->rt->consts[(k)])
#define FS_TMPL(i) (c->rt->tmpls[(i)])
#define FS_TRUE (c->rt->true_a)
#define FS_FALSE (c->rt->false_a)

int fs_compare(FsCall *c, FsCmp op, Atom *x, Atom *y);   /* 1 true, 0 false, -1 outside the compiled kinds */
bool fs_normal_form(FsCall *c, Atom *x);

FsRt *fs_open(cetta_engine_t *e, const FsPlan *plan, bool force_invalid, const char **error);
/* the profile an engine for this plan is opened with (NULL: CeTTa's default he profile) */
const char *fs_profile(const FsPlan *plan);
void fs_close(FsRt *rt);
const FsPlan *fs_find(const char *site);
const char *fs_shape_name(FsShape s);
extern const FsPlan *const fs_plans[];

#endif
